/* Lao Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Kham": "gold — Lao", "Souvanna": "golden — Sanskrit suvarna, via Pali", "Bounmy": "has merit — Pali punna (merit)", "Malay": "jasmine flower — Lao", "Noy": "little one — Lao", "Chanh": "moon — Sanskrit candra, via Pali", "Phomvihane": "Family name of Kaysone Phomvihane, founding leader of the Lao PDR.", "Siphandone": "Family name of Khamtai Siphandone, former president of Laos.", "Sayasone": "Family name of Choummaly Sayasone, former president of Laos.", "Sisoulith": "Family name of Thongloun Sisoulith, president of Laos."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Kham';
console.log(lookup(q));

